#!/usr/bin/env python3
"""versus2_oct28.py | freepracticesat.com | Oct 28, 2026
Adds five comparison posts (Kaplan, SAT question bank, Schoolhouse.world, Magoosh, College Panda),
their cards at the top of the blog page, and four sitemap entries.
Changes nothing unless blog/index.html and sitemap.xml look as expected.
Undo: python3 versus2_oct28.py --undo"""
import sys,os,json,base64,zlib,hashlib,shutil
C=json.loads('{"files": {"blog/freepracticesat-vs-college-panda.html": {"d": "", "h": "b895ff8fdcad45f1da0c903684a6919da2a0e925deefaccc3a35c301d1b5d909"}, "blog/freepracticesat-vs-kaplan.html": {"d": "", "h": "d2f9519e0248067adce2215e8f5c1bd81c5f20c2c3a76c8e58953361aacf686a"}, "blog/freepracticesat-vs-magoosh.html": {"d": "", "h": "b375f6c0b9991d6b493d1c44057534364de79e3916bea3261b099948c3468c83"}, "blog/freepracticesat-vs-sat-question-bank.html": {"d": "", "h": "d14ec65742c62a71546787ef828202d12677f57073b8d27857725ea941dd4fa5"}, "blog/freepracticesat-vs-schoolhouse-world.html": {"d": "", "h": "006301c077d7797d2441da4245585f0ae280b1882c9af8a2fae43b44be0266be"}}, "hr": "<hr class=\\"gold-rule\\">\\n", "cards": "<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-kaplan.html\\">\\n<p class=\\"meta\\">For Students &amp; Parents &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com or Kaplan? Three Students, Three Different Answers</h2>\\n<p>Kaplan courses run from $199 to tutoring packages from $1,999. Which students need a course, and which need to find out where their math points go.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-sat-question-bank.html\\">\\n<p class=\\"meta\\">For Students &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com and College Board\'s Question Bank: Which to Use When</h2>\\n<p>Official questions sorted by skill, or full tests that find your mistakes. Both are free, and they do different jobs.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-schoolhouse-world.html\\">\\n<p class=\\"meta\\">For Students &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com and Schoolhouse.world: Free Practice and Free Tutoring</h2>\\n<p>Free small-group SAT bootcamps with peer tutors, and free math tests that name your mistakes. How a student can use both at once.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-magoosh.html\\">\\n<p class=\\"meta\\">For Students &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com vs Magoosh: $29 and $129, and What Each Buys You</h2>\\n<p>Magoosh is a year of video lessons for both sections. My site is free math tests that find your mistakes, plus a $29 plan. Who each one suits.</p>\\n</a>\\n<a class=\\"post-card\\" href=\\"/blog/freepracticesat-vs-college-panda.html\\">\\n<p class=\\"meta\\">For Students &middot; October 28, 2026</p>\\n<h2>freepracticeSAT.com and The College Panda\'s SAT Math Book</h2>\\n<p>A well-liked math book for students aiming high, and free tests that tell you which chapters you need. How to use the two together.</p>\\n</a>\\n", "smap": "  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-kaplan.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-sat-question-bank.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-schoolhouse-world.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-magoosh.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n  <url>\\n    <loc>https://freepracticesat.com/blog/freepracticesat-vs-college-panda.html</loc>\\n    <lastmod>2026-10-28</lastmod>\\n  </url>\\n"}')
BK='.versus2_backup_20261028'
EDIT=['blog/index.html','sitemap.xml']
sha=lambda b: hashlib.sha256(b).hexdigest()
rd=lambda p: open(p,'rb').read()
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    for f in EDIT: shutil.copyfile(os.path.join(BK,f.replace('/','_')),f)
    for f in C['files']:
        if os.path.exists(f): os.rename(f,os.path.join(BK,'removed_'+f.replace('/','_')))
    print('UNDONE: blog page and sitemap restored, the five posts removed. Click Republish.'); sys.exit()
blog=rd('blog/index.html'); site=rd('sitemap.xml')
if all(os.path.exists(f) and sha(rd(f))==v['h'] for f,v in C['files'].items()) and C['cards'].encode() in blog:
    print('Already done. Nothing to change.'); sys.exit()
bad=[]
if blog.count(C['hr'].encode())!=1: bad.append('blog/index.html (the gold rule line was not found exactly once)')
if blog.count(b'<!DOCTYPE')!=1: bad.append('blog/index.html (not exactly one DOCTYPE)')
if site.count(b'</urlset>')!=1: bad.append('sitemap.xml (end tag)')
for f in C['files']:
    if os.path.exists(f): bad.append(f+' (already exists)')
    if f.encode() in blog: bad.append('blog/index.html already links '+f)
if bad:
    print('STOP. Nothing was changed:'); print('\n'.join(bad)); sys.exit(1)
os.makedirs(BK,exist_ok=True)
for f in EDIT: shutil.copyfile(f,os.path.join(BK,f.replace('/','_')))
for f,v in C['files'].items():
    b=zlib.decompress(base64.b64decode(v['d'])); assert sha(b)==v['h']
    open(f,'wb').write(b)
hr=C['hr'].encode()
open('blog/index.html','wb').write(blog.replace(hr,hr+C['cards'].encode(),1))
open('sitemap.xml','wb').write(site.replace(b'</urlset>',C['smap'].encode()+b'</urlset>',1))
b2=rd('blog/index.html'); s2=rd('sitemap.xml')
ok=all(sha(rd(f))==v['h'] for f,v in C['files'].items()) and b2.count(b'<!DOCTYPE')==1 and s2.count(b'<loc>')==site.count(b'<loc>')+5
print('DONE: five comparison posts added to the blog and sitemap. Click Republish.' if ok else 'CHECK FAILED. Run: python3 versus2_oct28.py --undo')
